for (let i = 0; i < 3; i++) {
  const y1 = b - cuts[i] * sc - gap * i, y0 = b - cuts[i + 1] * sc - gap * i;
  const k = api.stag(t, i, {gap:1.1, dur:0.7, from:1.2});
  api.rect(x, y0, w, y1 - y0, {fill:cols[i], c:'fg', w:3, a:0.9});
  const my = (y0 + y1) / 2;
  api.text(rates[i], x + w/2, my + 8, {size:i === 0 ? 20 : 34, c:'ink', weight:700, align:'center', k});
  api.arrow(x + w + 8, my, x + w + 50, my, {k, c:'fg'});
}
